CREATE JSON INDEX jx4 ON dbo.t1 (j1) ON fg1;
CREATE JSON INDEX jx5 ON dbo.t1 (j1) ON "default";
CREATE JSON INDEX jx6 ON dbo.t1 (j1) WITH (ONLINE = OFF);

DECLARE @q VECTOR(3) = '[1, 2, 3]';
SELECT r.distance FROM VECTOR_SEARCH(TABLE = dbo.docs AS t, COLUMN = v1, SIMILAR_TO = @q, METRIC = 'dot', TOP_N = 10) AS r;
SELECT r.distance FROM VECTOR_SEARCH(TABLE = dbo.docs, COLUMN = v1, SIMILAR_TO = @q, METRIC = 'euclidean', TOP_N = 5) AS r;

CREATE EXTERNAL FILE FORMAT ff7 WITH (FORMAT_TYPE = DELIMITEDTEXT, FORMAT_OPTIONS (FIELD_TERMINATOR = ',', PARSER_VERSION = '2.0'));
CREATE EXTERNAL FILE FORMAT ff8 WITH (FORMAT_TYPE = RCFILE, SERDE_METHOD = 'org.apache.hadoop.hive.serde2.columnar.LazyBinaryColumnarSerDe');
CREATE EXTERNAL FILE FORMAT ff9 WITH (FORMAT_TYPE = RCFILE, SERDE_METHOD = 'org.apache.hadoop.hive.serde2.columnar.ColumnarSerDe', DATA_COMPRESSION = 'org.apache.hadoop.io.compress.DefaultCodec');

CREATE EXTERNAL FILE FORMAT ff10 WITH (FORMAT_TYPE = JSON, DATA_COMPRESSION = 'org.apache.hadoop.io.compress.SnappyCodec');
CREATE EXTERNAL FILE FORMAT ff11 WITH (FORMAT_TYPE = JSON, DATA_COMPRESSION = 'org.apache.hadoop.io.compress.GzipCodec');
CREATE EXTERNAL FILE FORMAT ff12 WITH (FORMAT_TYPE = JSON, DATA_COMPRESSION = 'org.apache.hadoop.io.compress.DefaultCodec');

CREATE SERVER AUDIT au7 TO URL WITH (RETENTION_DAYS = 10);
CREATE SERVER AUDIT au8 TO EXTERNAL_MONITOR;
CREATE SERVER AUDIT au9 TO APPLICATION_LOG WITH (OPERATOR_AUDIT = ON);

DECLARE @co TABLE (
  a int PRIMARY KEY WITH (COMPRESSION_DELAY = 0),
  b int UNIQUE WITH (COMPRESSION_DELAY = 10 MINUTES),
  c int UNIQUE WITH (DATA_COMPRESSION = COLUMNSTORE),
  d int UNIQUE WITH (DATA_COMPRESSION = COLUMNSTORE_ARCHIVE)
);
